static void testMasterAutomation(const File& root,Assets& assets){
    auto metadata=automationParametersToJson();
    for(int id=118;id<=121;++id){
        bool master=id<121;expect(!isSynthAutomation(id)&&validAutomationLink(id,-1,8)==master&&validAutomationLink(id,7,8)==!master,"new Master-only and channel-only destinations cannot alias one another");
        expect((bool)metadata[id]["channel"]==!master&&(bool)metadata[id]["master"]==master,"discovery exposes explicit channel and Master capabilities");
    }
    auto p=emptyProject();p.songMode=true;p.loop=false;p.bpm=120;p.master=1;p.tracks[7].instrument=Instrument::analog;p.tracks[7].volume=1.4f;p.tracks[7].cutoff=20000;p.tracks[7].send=.65f;p.tracks[7].synth.sustain=.8f;p.patterns[0].lanes[7]={{0,4,48,.9f},{0,4,55,.8f},{0,4,60,.7f}};Clip source;source.track=7;source.length=8;p.clips={source};p.delayReturn=.1f;p.delayFeedback=.1f;
    for(int id=118;id<=120;++id){
        auto base=p;if(id==119)base.delayReturn=1;
        auto reference=base;if(id==118)reference.delayReturn=1;else if(id==119)reference.delayFeedback=.8f;else reference.masterSoftClip=true;
        auto automated=base;auto curve=parameterCurve(id,-1,1,1);curve.length=8;curve.points.back().beat=8;automated.clips.push_back(curve);
        auto a=render(automated,assets,root,96000,127),b=render(reference,assets,root,96000,511),plain=render(base,assets,root,96000,257);double difference=0;float error=0;
        for(int ch=0;ch<2;++ch)for(int n=48000;n<96000;++n){error=jmax(error,std::abs(a.getSample(ch,n)-b.getSample(ch,n)));difference+=std::abs(a.getSample(ch,n)-plain.getSample(ch,n));}
        expect(error<3e-6&&difference>.1,"each Master processing target changes real audio and reaches its static reference");
    }
    auto shaped=p;for(int id=118;id<=120;++id){auto curve=parameterCurve(id,-1);curve.length=4;curve.points={{0,0,true},{.5,1,true},{1.5,0,true},{2.5,1,true},{4,0,true}};shaped.clips.push_back(curve);}
    auto a=render(shaped,assets,root,96000,127),b=render(shaped,assets,root,96000,511);bool exact=true;for(int ch=0;ch<2;++ch)for(int i=0;i<96000;++i)exact&=a.getSample(ch,i)==b.getSample(ch,i)&&std::isfinite(a.getSample(ch,i));expect(exact,"Master return/feedback slews and saturation crossfades are callback-size independent");
    RenderSettings format;format.bits=32;format.endBeat=4;format.tailSeconds=0;auto file=root.getChildFile("master-automation.wav");expect(renderAudio(shaped,assets,root,file,format).wasOk(),"Master processing automation exports with the shared renderer");String warning;auto audio=assets.load(file,warning);bool same=audio&&audio->frameCount()==96000;if(same)for(int ch=0;ch<2;++ch)for(int i=0;i<96000;++i)same&=std::abs(audio->audio.getSample(ch,i)-a.getSample(ch,i))<1e-6;expect(same,"float export matches live Master processing sample timing");
    format.startBeat=.75;format.endBeat=2.75;auto range=root.getChildFile("master-automation-range.wav");expect(renderAudio(shaped,assets,root,range,format).wasOk(),"ranged Master processing export warms delay and automation history");auto crop=assets.load(range,warning);same=crop&&crop->frameCount()==48000;if(same)for(int ch=0;ch<2;++ch)for(int i=0;i<48000;++i)same&=std::abs(crop->audio.getSample(ch,i)-a.getSample(ch,i+18000))<1e-6;expect(same,"ranged Master processing audio matches a crop of the complete render");
    auto muted=p;muted.tracks[7].mute=true;muted.delayReturn=0;muted.tracks[7].send=0;for(auto& n:muted.patterns[0].lanes[7])n.length=8;auto unmuted=muted;unmuted.tracks[7].mute=false;
    auto curve=parameterCurve(121,7,0,0);curve.length=4;curve.points.back().beat=4;muted.clips.push_back(curve);auto active=render(muted,assets,root,96000,127),normal=render(unmuted,assets,root,96000,511);same=true;for(int ch=0;ch<2;++ch)for(int i=0;i<96000;++i)same&=active.getSample(ch,i)==normal.getSample(ch,i);expect(same&&active.getRMSLevel(0,24000,24000)>.01f,"mute automation can unmute an originally muted source without dropping its scheduled notes");
    muted.clips[1].points={{0,0,true},{.5,1,true},{1.5,0,true},{4,0,true}};active=render(muted,assets,root,96000,127);auto blocks=render(muted,assets,root,96000,511);same=true;for(int ch=0;ch<2;++ch)for(int i=0;i<96000;++i)same&=active.getSample(ch,i)==blocks.getSample(ch,i);expect(same&&active.getRMSLevel(0,18000,12000)<1e-6f,"held mute changes fade channel audio and remain callback-size independent");float restoreError=0;for(int ch=0;ch<2;++ch)for(int i=48000;i<72000;++i)restoreError=jmax(restoreError,std::abs(active.getSample(ch,i)-normal.getSample(ch,i)));expect(restoreError<1e-6,"unmuting resumes held notes at their continuing voice state");
    auto solo=muted;solo.tracks[0].solo=true;expect(render(solo,assets,root,48000).getMagnitude(0,48000)==0,"mute automation never bypasses static Solo exclusion");
    auto bus=unmuted;bus.tracks[6].isBus=true;bus.tracks[6].volume=1;bus.tracks[6].cutoff=20000;bus.tracks[7].mixer.output=6;auto busCurve=parameterCurve(121,6,1,1);busCurve.length=8;busCurve.points.back().beat=8;bus.clips.push_back(busCurve);expect(render(bus,assets,root,48000).getRMSLevel(0,24000,24000)<1e-6,"bus mute automation controls its routed child audio");
    auto engine=makeEngine(muted,assets,root);AudioBuffer<float> scratch(2,512);engine->seekRequested.store(2);engine->render(scratch.getWritePointer(0),scratch.getWritePointer(1),512);expect(engine->automationReadout[7][121].load()==0&&scratch.getMagnitude(0,512)>.001f,"seeking inside an unmute curve chases an originally muted held note");engine->seekRequested.store(5);engine->render(scratch.getWritePointer(0),scratch.getWritePointer(1),512);expect(engine->automationReadout[7][121].load()==-1&&muted.tracks[7].mute&&scratch.getMagnitude(0,512)<1e-6,"mute clip end restores the static mute and clears its readout");
    auto looped=shaped;looped.loop=true;looped.markers={{"loop","Loop",.5,1,0}};looped.loopSection="loop";auto loop=makeEngine(looped,assets,root);loop->seekRequested.store(.999);loop->render(scratch.getWritePointer(0),scratch.getWritePointer(1),512);expect(loop->completedLoops.load()>0&&loop->automationReadout[maxTracks][118].load()==1&&loop->automationReadout[maxTracks][120].load()==1,"section-loop wrap chases Master delay and saturation destinations");
    auto state=projectToJson(shaped);Project read;expect(projectFromJson(state,read).wasOk()&&read.clips[1].automationTarget==118,"schema 31 persists Master processing curves");auto before=JSON::toString(projectToJson(read));state.getDynamicObject()->setProperty("schema",30);expect(projectFromJson(state,read).failed()&&JSON::toString(projectToJson(read))==before,"new processing targets mislabeled as schema 30 reject atomically");
    auto operations=JSON::parse(R"([{"op":"add_automation","track":7,"target":"master.delayReturn","targetTrack":-1,"beat":0,"length":4,"points":[{"beat":0,"value":0},{"beat":4,"value":1}]},{"op":"add_automation","track":7,"target":"channel.mute","targetTrack":7,"beat":0,"length":4,"points":[{"beat":0,"value":1,"hold":true},{"beat":4,"value":0}]}])");Project edited;expect(applyControlEdits(p,operations,edited).wasOk()&&edited.clips[1].automationTarget==118&&edited.clips[2].automationTarget==121,"named MCP edits author separate Master and mute curves");
    for(auto invalid:std::array<std::pair<int,int>,4>{{{118,7},{119,6},{120,0},{121,-1}}}){auto bad=projectToJson(edited);bad["clips"][1].getDynamicObject()->setProperty("automationTarget",invalid.first);bad["clips"][1].getDynamicObject()->setProperty("automationTrack",invalid.second);before=JSON::toString(projectToJson(read));expect(projectFromJson(bad,read).failed()&&JSON::toString(projectToJson(read))==before,"misdirected Master/channel targets reject without replacing a loaded project");}
}
